import { getContext, setContext } from "svelte";

export interface FloatingContextValue {
	registerElement: (id: string, element: HTMLDivElement, depth: number) => void;
	unregisterElement: (id: string) => void;
}

const FLOATING_CONTEXT_KEY = Symbol("floating-context");

export function setFloatingContext(value: FloatingContextValue): FloatingContextValue {
	setContext(FLOATING_CONTEXT_KEY, value);
	return value;
}

export function useFloatingContext(): FloatingContextValue | undefined {
	return getContext<FloatingContextValue | undefined>(FLOATING_CONTEXT_KEY);
}

import Floating from "./floating.svelte";
import FloatingElement from "./floating-element.svelte";

export { Floating as ParallaxFloating, Floating, FloatingElement };
export type { FloatingProps } from "./floating.svelte";
export type { FloatingElementProps } from "./floating-element.svelte";

import { onMount } from "svelte";

export interface MousePosition {
	x: number;
	y: number;
}

export function useMousePosition(
	getContainer?: () => HTMLElement | SVGElement | null
): MousePosition {
	let position = $state<MousePosition>({ x: 0, y: 0 });

	onMount(() => {
		function updatePosition(x: number, y: number) {
			const container = getContainer?.();

			if (container) {
				const rect = container.getBoundingClientRect();
				position.x = x - rect.left;
				position.y = y - rect.top;
				return;
			}

			position.x = x;
			position.y = y;
		}

		function handleMouseMove(event: MouseEvent) {
			updatePosition(event.clientX, event.clientY);
		}

		function handleTouchMove(event: TouchEvent) {
			const touch = event.touches[0];

			if (touch) {
				updatePosition(touch.clientX, touch.clientY);
			}
		}

		window.addEventListener("mousemove", handleMouseMove);
		window.addEventListener("touchmove", handleTouchMove);

		return () => {
			window.removeEventListener("mousemove", handleMouseMove);
			window.removeEventListener("touchmove", handleTouchMove);
		};
	});

	return position;
}
